def count(folder):
    d = ROOT / folder
    if not d.is_dir():
        return None
    return sum(1 for f in d.iterdir() if f.is_file() and f.suffix in ('.py', '.sh', '.command', '.bat'))


def main():
    e = html.escape
    rel = lambda p: '../' + p
    missing = [p for *_, folders, scripts in CATEGORIES for p in list(folders) + [s for s, _ in scripts] if not (ROOT / p).exists()]
    missing += [q for _, _, opens, code, records, _ in TOOLS for q in opens + code + records if not (ROOT / q).exists()]
    now = datetime.date.today().strftime('%-d %B %Y')
    css = ('body{font:15px/1.5 -apple-system,Helvetica,Arial,sans-serif;color:#1b1b1b;background:#fff;max-width:74em;margin:2em auto;padding:0 1em}'
           'h1{font-size:1.5em}h2{font-size:1.2em;margin-top:1.8em}'
           'table{border-collapse:collapse;width:100%;margin:.8em 0}th,td{border:1px solid #c8c8c8;padding:.35em .55em;vertical-align:top;text-align:left}'
           'th{background:#f4f4f4}td.cat{width:17%}td.cat b{display:block}.box{border:1px solid #c8c8c8;background:#f4f4f4;padding:.6em .9em;margin:.8em 0;break-inside:avoid}'
           'a{color:#0b5394}.small{font-size:.9em;color:#555}tr{break-inside:avoid}'
           '@media print{@page{size:auto;margin:14mm}body{max-width:none;margin:0;font-size:10pt;color:#000;background:#fff}div,table{overflow-x:visible}a{color:#000;text-decoration:none}}')
    h = [f'<!DOCTYPE html><html lang="en-GB"><head><meta charset="utf-8"><title>Scripts map of the PPML review</title><style>{css}</style></head><body>',
         '<h1>Scripts map of the PPML review</h1>',
         f'<p class="small">Regenerated {e(now)} by <a href="{rel("scripts/paper_ppml/scripts_map.py")}">scripts/paper_ppml/scripts_map.py</a>. Every link opens the file or folder in the workspace. '
         'Rule of the workspace: whenever a script is added, retired, moved or changes purpose, the generator\'s categories and change log are updated and this page regenerated in the same step.</p>',
         '<div class="box"><b>How the paper is produced.</b> Nothing in the paper is typed from memory: every count comes from the evidence sheets through the data modules; every figure is drawn by a script as '
         'vector graphics from the same numbers; the build fills the text\'s placeholders, checks every number in every marked sentence against the cited record and refuses leftovers; independent scripts recount '
         'the tables and test the worded claims; the reference list comes from the database exports. Runbooks: '
         f'<a href="{rel("scripts/README.md")}">scripts/README.md</a>, <a href="{rel("search-ppml/README.md")}">search-ppml/README.md</a>, <a href="{rel("notes-verifier/README.md")}">notes-verifier/README.md</a>, '
         f'<a href="{rel("local-checker/README.md")}">local-checker/README.md</a>; the plan of each version: <a href="{rel("myliteraturereviewpaper/ppml2026/")}">myliteraturereviewpaper/ppml2026/PLAN-V&lt;n&gt;.md</a>.</div>',
         '<h2>1. Scripts by purpose</h2><p>One row per purpose: the folders it lives in (with the number of scripts each holds) and the scripts worth naming; the folder links cover the rest.</p>',
         '<table><tr><th>Purpose</th><th style="width:20%">Folders</th><th>Scripts worth naming</th><th style="width:14%">Part of the paper</th></tr>']
    for c, w, part, folders, scripts in CATEGORIES:
        fl = '<br>'.join(f'<a href="{rel(f)}">{e(f)}</a>' + (f' <span class="small">({n})</span>' if (n := count(f)) else '') for f in folders)
        sl = '<br>'.join(f'<a href="{rel(s)}">{e(s.split("/")[-1])}</a> <span class="small">{e(r)}</span>' for s, r in scripts) or '<span class="small">see the folders</span>'
        h.append(f'<tr><td class="cat"><b>{e(c)}</b><span class="small">{e(w)}</span></td><td>{fl}</td><td>{sl}</td><td class="small">{e(part)}</td></tr>')
    h.append('</table>')
    h.append('<h2>2. The tools</h2><p>The apps the author works in: what each is for, how it opens, its code and the records it reads or writes.</p>')
    h.append('<table><tr><th style="width:13%">Tool</th><th>For</th><th style="width:15%">Open with</th><th style="width:17%">Code</th><th style="width:17%">Records</th><th style="width:12%">Part of the paper</th></tr>')
    links = lambda paths: '<br>'.join(f'<a href="{rel(q)}">{e(q.split("/")[-1] or q)}</a>' for q in paths) or '—'
    for name, what, opens, code, records, part in TOOLS:
        h.append(f'<tr><td><b>{e(name)}</b></td><td>{e(what)}</td><td>{links(opens)}</td><td>{links(code)}</td><td>{links(records)}</td><td class="small">{e(part)}</td></tr>')
    h.append('</table>')
    h.append('<h2>3. Change log</h2><table><tr><th style="width:14%">Date</th><th>Change</th></tr>')
    for when, what in CHANGELOG:
        h.append(f'<tr><td>{e(when)}</td><td>{e(what)}</td></tr>')
    h.append('</table></body></html>')
    OUT.write_text('\n'.join(h), encoding='utf-8')
    print(f'{OUT.relative_to(ROOT)}: {len(CATEGORIES)} purposes, {len(TOOLS)} tools' + (f'; NOT ON DISK: {missing}' if missing else '; every link resolves'))


if __name__ == '__main__':
    main()
